(function(root,factory){if(typeof module==='object')module.exports=factory();else root.DragonEngine=factory()})(typeof window==='object'?window:this,()=>{
const learning=()=>typeof ArcadeLearning!=='undefined'?ArcadeLearning:(typeof window!=='undefined'?window.ArcadeLearning:null);
function recordPractice(owner,correct,timeout=false){const api=learning(),q=owner.question;if(!api?.active||!q||q.completed||owner.practiceAnsweredQuestion===q)return false;owner.practiceAnsweredQuestion=q;api.record(q,correct,undefined,{timeout});return true;}
class Flight{
 constructor(o={}){this.random=o.random||Math.random;this.timed=!!o.timed;this.op=o.operation||'add';this.range=o.range||10;this.total=this.timed?Infinity:12;this.passed=0;this.hearts=3;this.streak=0;this.charge=0;this.coins=0;this.level=1;this.x=.5;this.y=.5;this.targetX=.5;this.time=0;this.elapsed=0;this.duration=3;this.ready=false;this.cooldown=0;this.active=true;this.power=false;this.events=[];this.enemies=[];this.shots=[];this.enemyId=0;this.shotId=0;this.question=this.makeQuestion();this.fillEnemies();}
 makeQuestion(){if(learning()?.active)return learning().next();const a=1+Math.floor(this.random()*this.range),b=1+Math.floor(this.random()*this.range),op=this.op==='mix'?['add','sub','mul','div'][Math.floor(this.random()*4)]:this.op;const answer=op==='add'?a+b:op==='mul'?a*b:b,text=op==='add'?a+' + '+b:op==='mul'?a+' × '+b:op==='sub'?(a+b)+' − '+a:(a*b)+' ÷ '+a;const values=new Set([answer]);for(const n of [answer+1,answer-1,answer+a,answer+b,answer+2,answer-2])if(n>=0&&values.size<4)values.add(n);while(values.size<4)values.add(answer+values.size);const choices=[...values];for(let i=choices.length-1;i>0;i--){const j=Math.floor(this.random()*(i+1));[choices[i],choices[j]]=[choices[j],choices[i]]}return{text,answer,choices};}
 fillEnemies(){while(this.enemies.length<Math.min(3,this.total-this.passed)){const id=++this.enemyId,x=.2+(id%3)*.3;this.enemies.push({id,x,z:0,age:0,side:id%2?1:-1,targeted:false,escaping:false});}}
 primary(){return this.enemies.find(e=>!e.targeted&&!e.escaping);}
 miss(timeout=false){if(this.ready||!this.active)return;const e=this.primary();recordPractice(this,false,timeout);this.streak=this.charge=0;this.power=false;this.ready=true;this.cooldown=1;this.hearts--;if(e){e.escaping=true;e.escapeAge=0;this.shots.push({id:++this.shotId,targetId:e.id,elapsed:0,duration:.72,power:false,miss:true,side:this.random()<.5?-1:1,fromX:this.x,x:e.x,z:e.z});}this.events.push({type:timeout?'miss':'wrong',text:this.question.text,answer:this.question.answer,timeout,x:e?.x??.5,z:e?.z??.5});if(this.hearts<=0){if(this.timed){this.hearts=3;this.events.push({type:'recharge'});}else{this.hearts=0;this.endAfterMiss=true;}}}
 answer(value){if(this.question?.completed||!this.active||this.ready)return false;if(this.elapsed>=this.duration-1e-9){this.miss(true);return false;}if(value!==this.question.answer){this.miss(false);return false;}const available=this.enemies.filter(e=>!e.targeted&&!e.escaping);if(!available.length)return false;recordPractice(this,true);this.streak++;this.charge++;this.power=this.charge>=4;if(this.power)this.charge=0;this.ready=true;this.cooldown=.85;const targets=available.slice(0,this.power?3:1);this.targetX=targets[0].x;for(const enemy of targets){enemy.targeted=true;const shot={id:++this.shotId,targetId:enemy.id,elapsed:0,duration:.65,power:this.power,fromX:this.x,x:enemy.x,z:enemy.z};this.shots.push(shot);this.events.push({type:'shot',id:shot.id,targetId:enemy.id,power:this.power,x:enemy.x,z:enemy.z});}if(this.power)this.events.push({type:'dash'});return true;}
 update(dt){if(!this.active||!Number.isFinite(dt)||dt<=0)return;let remaining=dt;while(remaining>1e-9&&this.active){const step=Math.min(.025,remaining);remaining-=step;this.time+=step;this.x+=(this.targetX-this.x)*(1-Math.exp(-step*3));for(const e of this.enemies){e.age+=step;e.z=Math.min(.9,e.age*.1);if(e.escaping)e.escapeAge+=step;}
  for(const shot of this.shots){shot.elapsed+=step;const enemy=this.enemies.find(e=>e.id===shot.targetId);if(enemy){shot.x=enemy.x;shot.z=enemy.z;}if(shot.elapsed+1e-9>=shot.duration){shot.done=true;if(enemy&&!shot.miss){this.enemies=this.enemies.filter(e=>e.id!==enemy.id);this.passed++;this.level=1+Math.floor(this.passed/4);const coins=shot.power?50:25;this.coins+=coins;this.events.push({type:'pass',coins,power:shot.power,passed:this.passed,x:enemy.x,z:enemy.z,targetId:enemy.id,pose:{...enemy}});if(this.passed>=this.total){this.active=false;this.events.push({type:'win'});break;}}}}
  this.shots=this.shots.filter(s=>!s.done);this.enemies=this.enemies.filter(e=>!e.escaping||e.escapeAge<.85);if(!this.active)break;
  if(this.ready){this.cooldown-=step;if(this.cooldown<=1e-9){if(this.endAfterMiss){this.active=false;this.events.push({type:'over'});break;}this.ready=false;this.fillEnemies();for(const e of this.enemies)if(!e.targeted)e.age=0;this.question=this.makeQuestion();this.elapsed=0;return;}}else{this.elapsed+=step;if(this.elapsed+1e-9>=this.duration)this.miss(true);}
  this.fillEnemies();
 }}
 get progress(){return Math.min(1,this.elapsed/this.duration);}drain(){const events=this.events;this.events=[];return events;}
}return{Flight};});
